#include "PPU.h"
uint8_t PPU::CpuRead(uint16_t address) { const uint8_t r=static_cast<uint8_t>(address&7); if(r==2){uint8_t v=regs_[2]; regs_[2]&=0x7F; addressLatch_=false; return v;} if(r==7){uint8_t v=address<0x2000?cartridge_->PpuRead(address):vram_[(address-0x2000)%vram_.size()]; address+=0x20; return v;} return regs_[r]; }
void PPU::CpuWrite(uint16_t address,uint8_t value) { const uint8_t r=static_cast<uint8_t>(address&7); regs_[r]=value; if(r==6){if(!addressLatch_) temp_=value<<8; else {address_=static_cast<uint16_t>(temp_|value); } addressLatch_=!addressLatch_;} if(r==7){if(address_<0x2000) cartridge_->PpuWrite(address_,value); else if(address_<0x3F00) vram_[(address_-0x2000)%vram_.size()]=value; address_+=0x20;} }
void PPU::Step() { ++cycle_; if(cycle_>=341){cycle_=0; ++scanline_;} if(scanline_>=241&&scanline_<261) regs_[2]|=0x80; if(scanline_==261){scanline_=0; regs_[2]&=0x1F; for(int y=0;y<240;++y) for(int x=0;x<256;++x){const uint8_t c=cartridge_?cartridge_->PpuRead(static_cast<uint16_t>(((y/8)*32+(x/8))*16+(y&7))):0; frame_[y*256+x]=0xFF000000u|((c*37u)&255u)<<16|((c*71u)&255u)<<8|(c*113u); } frameReady_=true;} }
